pub fn column() -> Div {
    div().min_w_0().flex().flex_col()
}
pub fn row() -> Div {
    div().min_w_0().flex().items_center()
}
pub fn frame(width: f32, p: Paint) -> Div {
    column()
        .w(px(width))
        .max_w_full()
        .gap_3()
        .p_4()
        .rounded(crate::foundation::SURFACE_RADIUS)
        .bg(p.panel)
        .border_1()
        .border_color(p.line)
        .text_color(p.ink)
}
